cd /workspace/project && python3 -c "
import os
total=0; n=0
for root, dirs, files in os.walk('.'):
    for d in dirs:
        if d != '__pycache__':
            print('dir', os.path.join(root,d)); n+=1
    for f in files:
        p=os.path.join(root,f); s=os.path.getsize(p)
        if not p.endswith('.pyc'):
            print('%8d %s' % (s,p)); total+=s; n+=1
print('entries:', n, 'bytes:', total)
"
